/**
 * Saldo dia a dia dentro de um mês.
 *
 * `TimelineMonth.days` só tem os dias com movimento — bom para extrato, ruim
 * para gráfico: um mês com lançamento no dia 1 e no dia 28 viraria uma reta de
 * dois pontos, escondendo que o saldo ficou 27 dias no fundo do poço. Aqui todo
 * dia do mês existe, carregando o saldo do anterior.
 */

import { monthRange, type YearMonth } from '@/core/month';
import type { TimelineEvent, TimelineMonth } from '@/core/timeline';

export type DayPoint = {
  date: string;
  /** Dia do mês, 1–31. */
  day: number;
  /** Saldo no fim do dia. */
  balanceCents: number;
  inCents: number;
  outCents: number;
  hasEvents: boolean;
  /** O que aconteceu no dia. Vazio quando o saldo só foi carregado adiante. */
  events: readonly TimelineEvent[];
  /** Posterior a hoje: o saldo aqui é projeção, não fato. */
  projected: boolean;
  /** É hoje. */
  isToday: boolean;
  belowMinimum: boolean;
};

export type DailySeriesInput = {
  month: TimelineMonth;
  today: string;
  /** Colchão: abaixo disto o dia entra na faixa de alerta. */
  minimumCents: number;
};

export function dailySeries(input: DailySeriesInput): DayPoint[] {
  const { month, today, minimumCents } = input;
  const { start, end } = monthRange(month.ym as YearMonth);

  const byDate = new Map(month.days.map((d) => [d.date, d]));
  const out: DayPoint[] = [];

  let balance = month.openingCents;
  const lastDay = Number(end.slice(8, 10));

  for (let day = 1; day <= lastDay; day++) {
    const date = `${start.slice(0, 8)}${String(day).padStart(2, '0')}`;
    const hit = byDate.get(date);
    if (hit) balance = hit.balanceCents;

    out.push({
      date,
      day,
      balanceCents: balance,
      inCents: hit?.inCents ?? 0,
      outCents: hit?.outCents ?? 0,
      hasEvents: Boolean(hit),
      events: hit?.events ?? [],
      projected: date > today,
      isToday: date === today,
      belowMinimum: balance < minimumCents,
    });
  }

  return out;
}

/** Dia de menor saldo. Empate fica com o primeiro — é quando o buraco abre. */
export function lowestPoint(points: ReadonlyArray<DayPoint>): DayPoint | null {
  let best: DayPoint | null = null;
  for (const p of points) {
    if (!best || p.balanceCents < best.balanceCents) best = p;
  }
  return best;
}

/** Menor saldo de hoje em diante — o que ainda dá para evitar. */
export function lowestAhead(
  points: ReadonlyArray<DayPoint>,
  today: string,
): DayPoint | null {
  return lowestPoint(points.filter((p) => p.date >= today));
}

import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  AlertTriangle,
  CalendarRange,
  ChevronLeft,
  ChevronRight,
  Plus,
  Wallet,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { EmptyState } from '@/components/ui/EmptyState';
import { Skeleton } from '@/components/ui/Skeleton';
import { MoneyText } from '@/components/money/MoneyText';
import { addMonths, formatMonth } from '@/core/month';
import {
  compareToAverage,
  dailySeries,
  monthMetrics,
} from '@/core/month-metrics';
import type { Occurrence } from '@/core/series';
import { BalanceByDayChart } from '@/features/panel/components/BalanceByDayChart';
import { CategoryBars } from '@/features/panel/components/CategoryBars';
import { MetricGrid } from '@/features/panel/components/MetricGrid';
import { ForecastNotice } from '@/features/panel/components/ForecastNotice';
import { MinimumControl } from '@/features/panel/components/MinimumControl';
import { useMinimumBalance } from '@/features/panel/hooks/useMinimumBalance';
import { DayRow } from '@/features/panel/components/DayRow';
import { MonthDashboard } from '@/features/panel/components/MonthDashboard';
import { MonthStrip } from '@/features/panel/components/MonthStrip';
import { EntrySheet } from '@/features/panel/components/EntrySheet';
import { usePanel } from '@/features/panel/hooks/usePanel';
import { cn } from '@/lib/cn';

function titleCase(v: string): string {
  return v.charAt(0).toUpperCase() + v.slice(1);
}

/**
 * A aplicação inteira.
 *
 * Um mês por vez: cabeçalho com os números, fita para pular entre meses, e a
 * sequência de dias embaixo. Previsto e realizado convivem na mesma lista
 * porque são a mesma coisa — a diferença é `status`, não a tela onde moram.
 */
export function PanelPage() {
  // Com contas separadas, "todos" soma dois caixas num número que não existe
  // em conta nenhuma. Serve para a visão da casa, nunca como padrão silencioso.
  const [owner, setOwner] = useState<string | null>(null);

  const {
    people,
    months,
    currentYm,
    today,
    todayBalanceCents,
    hasAnchor,
    unanchoredAccounts,
    forecast,
    categoryNameById,
    occurrenceById,
    templateById,
    isLoading,
    isError,
    refetch,
  } = usePanel({ personId: owner });

  const { data: minimumCents = 0 } = useMinimumBalance();

  const [selectedYm, setSelectedYm] = useState<string | null>(null);
  const [editing, setEditing] = useState<Occurrence | null>(null);
  const [creating, setCreating] = useState(false);
  // Extrato é a visão secundária: a primária é a análise acima dele.
  const [statementOpen, setStatementOpen] = useState(false);

  const ym = selectedYm ?? currentYm;
  const month = useMemo(() => months.find((m) => m.ym === ym), [months, ym]);
  const index = months.findIndex((m) => m.ym === ym);

  const isCurrent = ym === currentYm;
  const isFuture = ym > currentYm;
  const isPast = ym < currentYm;

  const points = useMemo(
    () => (month ? dailySeries({ month, today, minimumCents }) : null),
    [month, today, minimumCents],
  );

  const metrics = useMemo(
    () =>
      month && points
        ? monthMetrics({ month, points, today, minimumCents })
        : null,
    [month, points, today, minimumCents],
  );

  const comparison = useMemo(
    () =>
      month
        ? compareToAverage(
            month,
            months.filter((m) => m.ym < currentYm),
          )
        : null,
    [month, months, currentYm],
  );

  const entryCount = useMemo(
    () =>
      month
        ? month.days.reduce(
            (s, d) => s + d.events.filter((e) => e.kind !== 'forecast').length,
            0,
          )
        : 0,
    [month],
  );

  if (isLoading) {
    return (
      <div className="mx-auto max-w-3xl space-y-4">
        <Skeleton className="h-20 w-full rounded-xl" />
        <Skeleton className="h-28 w-full rounded-xl" />
        <Skeleton className="h-72 w-full rounded-xl" />
      </div>
    );
  }

  if (isError) {
    return (
      <EmptyState
        icon={CalendarRange}
        title="Não deu para carregar"
        description="Tente de novo em instantes."
        action={
          <Button variant="secondary" size="sm" onClick={refetch}>
            Tentar de novo
          </Button>
        }
      />
    );
  }

  if (!hasAnchor) {
    return (
      <EmptyState
        icon={Wallet}
        title="Informe um saldo para começar"
        description="Sem o saldo real de alguma conta não há de onde partir. Leva 10 segundos em Mais → Saldos reais."
        action={
          <Link to="/more">
            <Button>Informar saldo</Button>
          </Link>
        }
      />
    );
  }

  return (
    <div className="mx-auto max-w-3xl space-y-4 pb-24 animate-fade-in">
      <header className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-1">
          <NavButton
            label="Mês anterior"
            disabled={index <= 0}
            onClick={() => setSelectedYm(addMonths(ym, -1))}
          >
            <ChevronLeft className="size-4" aria-hidden />
          </NavButton>
          <h1 className="min-w-[9.5rem] text-center font-display text-lg font-semibold tracking-tight">
            {titleCase(formatMonth(ym, 'MMMM yyyy'))}
          </h1>
          <NavButton
            label="Próximo mês"
            disabled={index < 0 || index >= months.length - 1}
            onClick={() => setSelectedYm(addMonths(ym, 1))}
          >
            <ChevronRight className="size-4" aria-hidden />
          </NavButton>
        </div>

          <div className="flex items-center gap-3">
          {!isCurrent ? (
            <button
              type="button"
              onClick={() => setSelectedYm(currentYm)}
              className="rounded-md px-2 py-1 font-mono text-[10px] uppercase tracking-[0.08em] text-text-muted hover:text-text"
            >
              hoje
            </button>
          ) : null}
          {isCurrent ? (
            <div className="text-right">
              <p className="font-mono text-[9px] uppercase tracking-[0.1em] text-text-muted">
                Saldo agora
              </p>
              <p className="font-display text-sm font-semibold tabular-nums">
                <MoneyText
                  cents={todayBalanceCents ?? 0}
                  tone={(todayBalanceCents ?? 0) < 0 ? 'danger' : 'default'}
                />
              </p>
            </div>
          ) : null}
        </div>
      </header>

      {people.length > 1 ? (
        <div className="flex gap-1 rounded-lg border border-border bg-surface p-0.5">
          {[{ id: null, name: 'Casa' }, ...people].map((p) => (
            <button
              key={p.id ?? 'todos'}
              type="button"
              onClick={() => setOwner(p.id)}
              aria-pressed={owner === p.id}
              className={cn(
                'flex-1 rounded-md px-2 py-1.5 text-xs font-medium transition-colors',
                owner === p.id
                  ? 'bg-accent-muted text-accent'
                  : 'text-text-muted hover:text-text',
              )}
            >
              {p.name}
            </button>
          ))}
        </div>
      ) : null}

      {unanchoredAccounts.length > 0 && hasAnchor ? (
        <div className="flex items-start gap-2.5 rounded-xl border border-warning/30 bg-warning/[0.06] p-3">
          <AlertTriangle className="mt-0.5 size-4 shrink-0 text-warning" aria-hidden />
          <p className="text-[11px] leading-relaxed text-text-muted">
            <strong className="text-text">
              {unanchoredAccounts.map((a) => a.name).join(', ')}
            </strong>{' '}
            {unanchoredAccounts.length === 1 ? 'não tem' : 'não têm'} saldo real
            informado. Os lançamentos entram no fluxo, mas o ponto de partida
            ignora {unanchoredAccounts.length === 1 ? 'essa conta' : 'essas contas'} —
            o saldo está deslocado por um valor desconhecido.{' '}
            <Link to="/settings" className="text-accent underline-offset-2 hover:underline">
              Informar saldo
            </Link>
          </p>
        </div>
      ) : null}

      <MonthStrip
        months={months}
        selectedYm={ym}
        currentYm={currentYm}
        onSelect={setSelectedYm}
      />

      {month && points ? (
        <>
          <MonthDashboard
            month={month}
            isCurrent={isCurrent}
            isFuture={isFuture}
          />

          <BalanceByDayChart
            points={points}
            minimumCents={minimumCents}
            lowest={metrics?.lowest ?? null}
          />

          <ForecastNotice forecast={forecast} relevant={!isPast} />

          <MinimumControl cents={minimumCents} />

          {metrics ? (
            <MetricGrid
              metrics={metrics}
              phase={isFuture ? 'future' : isCurrent ? 'current' : 'past'}
              minimumCents={minimumCents}
              comparison={comparison}
            />
          ) : null}

          <CategoryBars month={month} categoryNameById={categoryNameById} />

          <section className="overflow-hidden rounded-xl border border-border bg-surface">
            <button
              type="button"
              onClick={() => setStatementOpen((v) => !v)}
              aria-expanded={statementOpen}
              className="flex w-full items-center gap-2 px-4 py-3 text-left hover:bg-surface-hover"
            >
              <ChevronRight
                className={cn(
                  'size-4 shrink-0 text-text-muted transition-transform',
                  statementOpen && 'rotate-90',
                )}
                aria-hidden
              />
              <span className="font-mono text-[10px] uppercase tracking-[0.12em] text-text-muted">
                Extrato do mês
              </span>
              <span className="ml-auto font-mono text-[11px] tabular-nums text-text-muted">
                {entryCount} {entryCount === 1 ? 'lançamento' : 'lançamentos'}
              </span>
            </button>

            {statementOpen ? (
              month.days.length === 0 ? (
                <p className="border-t border-border px-4 py-8 text-center text-[13px] text-text-muted">
                  Nenhum movimento neste mês — o saldo segue em{' '}
                  <MoneyText
                    cents={month.closingCents}
                    className="text-[13px] text-text"
                  />
                  .
                </p>
              ) : (
                <ul className="border-t border-border">
                  {month.days.map((day) => (
                    <DayRow
                      key={day.date}
                      day={day}
                      categoryNameById={categoryNameById}
                      isToday={day.date === today}
                      onSelect={(event) => {
                        const occurrence = occurrenceById.get(event.id);
                        if (occurrence) setEditing(occurrence);
                      }}
                    />
                  ))}
                </ul>
              )
            ) : null}
          </section>

        </>
      ) : null}

      <button
        type="button"
        onClick={() => setCreating(true)}
        aria-label="Novo lançamento"
        className={cn(
          'fixed bottom-[calc(4.5rem+var(--spacing-safe-bottom))] right-4 z-30 flex items-center gap-2',
          'rounded-pill bg-accent px-4 py-3 font-medium text-accent-fg shadow-lg',
          'hover:brightness-105 sm:bottom-6',
        )}
      >
        <Plus className="size-4" aria-hidden />
        Lançamento
      </button>

      <EntrySheet
        open={creating || editing != null}
        occurrence={editing}
        template={editing?.seriesId ? (templateById.get(editing.seriesId) ?? null) : null}
        defaultYm={ym}
        today={today}
        onClose={() => {
          setCreating(false);
          setEditing(null);
        }}
      />
    </div>
  );
}

function NavButton({
  label,
  disabled,
  onClick,
  children,
}: {
  label: string;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        'flex size-8 items-center justify-center rounded-md text-text-muted',
        'hover:bg-surface-hover hover:text-text disabled:opacity-30 disabled:hover:bg-transparent',
      )}
    >
      {children}
    </button>
  );
}

import { useMemo } from 'react';
import { cashBalanceAt } from '@/core/cashflow';
import { forecastVariable, type VariableForecast } from '@/core/forecast';
import { addMonths, currentYearMonth, monthRange } from '@/core/month';
import { expandSeries, type Occurrence } from '@/core/series';
import {
  buildTimelineEvents,
  groupTimeline,
  plannedCategoriesIn,
  timelineMonths,
  type TimelineMonth,
} from '@/core/timeline';
import { useLatestBalances } from '@/features/balances/hooks/useBalances';
import {
  useAccounts,
  useCategories,
  usePeopleQuery,
} from '@/features/capture/hooks/useCaptureLookups';
import { useTimelineRows } from '@/features/transactions/hooks/useTransactions';
import type { Transaction } from '@/types/models';

/** Meses de histórico usados para estimar o variável. */
const HISTORY_MONTHS = 6;

export type UsePanelOptions = {
  past?: number;
  future?: number;
  /**
   * De quem é o caixa. `null` = todo mundo.
   *
   * Com contas separadas, somar as duas pessoas num saldo só produz um número
   * que não existe em conta nenhuma. O recorte é por **dono da conta**, não por
   * `person_id` do lançamento: dinheiro vive em conta.
   */
  personId?: string | null;
};

export type PersonOption = { id: string; name: string };

export type PanelResult = {
  /** Pessoas que têm conta própria — quem pode ser recorte. */
  people: PersonOption[];
  /** Meses em ordem cronológica, passado → futuro. */
  months: TimelineMonth[];
  currentYm: string;
  today: string;
  /** Saldo real de hoje — só realizado. Null sem âncora. */
  todayBalanceCents: number | null;
  hasAnchor: boolean;
  /**
   * Contas de caixa no recorte que ninguém ancorou.
   *
   * Os lançamentos delas entram no fluxo mas não no ponto de partida, então o
   * saldo fica deslocado por um valor desconhecido. Silenciar isso faria a
   * visão da casa somar o caixa de um com o fluxo do outro.
   */
  unanchoredAccounts: { id: string; name: string }[];
  forecast: VariableForecast | null;
  categoryNameById: Map<string, string>;
  /** Ocorrência por id de evento — a edição precisa dela, não do evento. */
  occurrenceById: Map<string, Occurrence>;
  /** Linha-modelo por id de série. */
  templateById: Map<string, Transaction>;
  isLoading: boolean;
  isError: boolean;
  refetch: () => void;
};

function todayIso(): string {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${day}`;
}

/**
 * Fonte única de números da aplicação.
 *
 * Uma tela só, um cálculo só. Quando havia Painel, Mês, Futuro e Plano cada um
 * com seu cálculo, as telas discordavam entre si — foi assim que o app passou a
 * errar julho em R$ 9.090.
 */
export function usePanel(options: UsePanelOptions = {}): PanelResult {
  const past = options.past ?? 6;
  const future = options.future ?? 12;
  const personId = options.personId ?? null;

  const today = todayIso();
  const currentYm = currentYearMonth();

  const accountsQuery = useAccounts();
  const peopleQuery = usePeopleQuery();
  const categoriesQuery = useCategories();
  const balancesQuery = useLatestBalances();

  const months = useMemo(
    () => timelineMonths(currentYm, past, future),
    [currentYm, past, future],
  );

  // Só meses fechados: o corrente ainda está pela metade e, se entrar na
  // mediana (escalado), puxa o estimado de todos os futuros.
  const historyMonths = useMemo(
    () =>
      Array.from({ length: HISTORY_MONTHS }, (_, i) =>
        addMonths(currentYm, i - HISTORY_MONTHS),
      ),
    [currentYm],
  );

  // Janela larga: cobre a âncora, o histórico e todo o passado exibido.
  const anchorDates = (balancesQuery.data ?? []).map((b) => b.asOfDate);
  const windowFrom = [
    ...anchorDates,
    monthRange(months[0]!).start,
    monthRange(historyMonths[0]!).start,
  ].sort()[0]!;
  const windowTo = monthRange(months.at(-1)!).end;
  const rowsQuery = useTimelineRows(windowFrom, windowTo);

  const isLoading =
    accountsQuery.isLoading ||
    categoriesQuery.isLoading ||
    balancesQuery.isLoading ||
    rowsQuery.isLoading;
  const isError =
    accountsQuery.isError ||
    categoriesQuery.isError ||
    balancesQuery.isError ||
    rowsQuery.isError;

  /** Contas do recorte. Sem dono definido a conta é da casa e entra em todos. */
  const scopedAccounts = useMemo(
    () =>
      (accountsQuery.data ?? []).filter(
        (a) =>
          !a.archived &&
          (personId == null || a.person_id === personId || a.person_id == null),
      ),
    [accountsQuery.data, personId],
  );

  const scopedAccountIds = useMemo(
    () => new Set(scopedAccounts.map((a) => a.id)),
    [scopedAccounts],
  );

  const cashAccountIds = useMemo(
    () => new Set(scopedAccounts.filter((a) => a.kind !== 'credit').map((a) => a.id)),
    [scopedAccounts],
  );

  const unanchoredAccounts = useMemo(() => {
    const anchored = new Set(
      (balancesQuery.data ?? []).map((b) => b.accountId),
    );
    return scopedAccounts
      .filter((a) => a.kind !== 'credit' && !anchored.has(a.id))
      .map((a) => ({ id: a.id, name: a.name }));
  }, [balancesQuery.data, scopedAccounts]);

  const anchors = useMemo(
    () =>
      (balancesQuery.data ?? [])
        .filter((b) => cashAccountIds.has(b.accountId))
        .map((b) => ({
          accountId: b.accountId,
          balanceCents: b.balanceCents,
          asOfDate: b.asOfDate,
        })),
    [balancesQuery.data, cashAccountIds],
  );

  /** Linhas do recorte: conta de origem pertence a quem está sendo olhado. */
  const scopedRows = useMemo(
    () =>
      (rowsQuery.data ?? []).filter(
        (t) => t.accountId == null || scopedAccountIds.has(t.accountId),
      ),
    [rowsQuery.data, scopedAccountIds],
  );

  /** Só o realizado move saldo de verdade. Previsto é expectativa. */
  const actualTxs = useMemo(
    () =>
      scopedRows
        .filter((t) => t.status === 'actual' && t.recurrence === 'none')
        .map((t) => ({
          date: t.date,
          kind: t.kind,
          amountCents: t.amountCents,
          accountId: t.accountId,
          transferAccountId: t.transferAccountId,
        })),
    [scopedRows],
  );

  const occurrences = useMemo(() => {
    if (!rowsQuery.data) return [];
    return expandSeries({
      rows: scopedRows.map((t) => ({
        id: t.id,
        date: t.date,
        kind: t.kind,
        amountCents: t.amountCents,
        description: t.description,
        categoryId: t.categoryId,
        accountId: t.accountId,
        transferAccountId: t.transferAccountId,
        personId: t.personId,
        status: t.status,
        recurrence: t.recurrence,
        recurrenceEnd: t.recurrenceEnd,
        seriesId: t.seriesId,
      })),
      fromYm: months[0]!,
      toYm: months.at(-1)!,
    });
  }, [rowsQuery.data, scopedRows, months]);

  /** Saldo no dia anterior ao primeiro mês exibido — onde a linha começa. */
  const openingCents = useMemo(() => {
    if (anchors.length === 0 || !rowsQuery.data) return null;
    return cashBalanceAt({
      anchors,
      transactions: actualTxs,
      date: monthRange(addMonths(months[0]!, -1)).end,
      cashAccountIds,
    }).cents;
  }, [anchors, rowsQuery.data, actualTxs, months, cashAccountIds]);

  const todayBalanceCents = useMemo(() => {
    if (anchors.length === 0 || !rowsQuery.data) return null;
    return cashBalanceAt({
      anchors,
      transactions: actualTxs,
      date: today,
      cashAccountIds,
    }).cents;
  }, [anchors, rowsQuery.data, actualTxs, today, cashAccountIds]);

  const forecast = useMemo(() => {
    if (!rowsQuery.data) return null;
    return forecastVariable({
      transactions: scopedRows
        .filter((t) => t.status === 'actual')
        .map((t) => ({
          date: t.date,
          kind: t.kind,
          amountCents: t.amountCents,
          categoryId: t.categoryId,
        })),
      months: historyMonths,
      // Categoria já coberta por um previsto não entra na média: seria dobrar.
      plannedCategoryIds: plannedCategoriesIn(occurrences),
    });
  }, [rowsQuery.data, scopedRows, historyMonths, occurrences]);

  const grouped = useMemo((): TimelineMonth[] => {
    if (!rowsQuery.data || openingCents == null) return [];

    const events = buildTimelineEvents({
      occurrences,
      months,
      today,
      cashAccountIds,
      forecastMonthlyCents: forecast?.totalMonthlyCents ?? 0,
    });

    const all = groupTimeline({ events, anchorCents: openingCents, months });

    // Meses vazios antes do primeiro movimento só achatam a fita e enchem a
    // navegação. O futuro fica, mesmo vazio: ali a ausência é informação.
    const firstWithData = all.findIndex((m) => m.days.length > 0);
    if (firstWithData <= 0) return all;
    const currentIndex = all.findIndex((m) => m.ym === currentYm);
    return all.slice(Math.min(firstWithData, Math.max(0, currentIndex)));
  }, [
    rowsQuery.data,
    occurrences,
    openingCents,
    months,
    today,
    cashAccountIds,
    forecast,
    currentYm,
  ]);

  /** Quem tem conta própria — só esses podem ser recorte. */
  const people = useMemo((): PersonOption[] => {
    const owners = new Set(
      (accountsQuery.data ?? [])
        .filter((a) => !a.archived && a.person_id)
        .map((a) => a.person_id!),
    );
    return (peopleQuery.data ?? [])
      .filter((p) => owners.has(p.id))
      .map((p) => ({ id: p.id, name: p.short_name || p.name }));
  }, [accountsQuery.data, peopleQuery.data]);

  const occurrenceById = useMemo(
    () => new Map(occurrences.map((o) => [o.id, o])),
    [occurrences],
  );

  const templateById = useMemo(
    () =>
      new Map(
        (rowsQuery.data ?? [])
          .filter((t) => t.recurrence !== 'none')
          .map((t) => [t.id, t]),
      ),
    [rowsQuery.data],
  );

  const categoryNameById = useMemo(
    () => new Map((categoriesQuery.data ?? []).map((c) => [c.id, c.name])),
    [categoriesQuery.data],
  );

  function refetch() {
    void accountsQuery.refetch();
    void categoriesQuery.refetch();
    void balancesQuery.refetch();
    void rowsQuery.refetch();
  }

  return {
    people,
    months: grouped,
    currentYm,
    today,
    todayBalanceCents,
    hasAnchor: anchors.length > 0,
    unanchoredAccounts,
    forecast,
    categoryNameById,
    occurrenceById,
    templateById,
    isLoading,
    isError,
    refetch,
  };
}

import { describe, expect, it } from 'vitest';
import {
  buildTimelineEvents,
  dueDateInMonth,
  groupTimeline,
  occurrenceDelta,
  plannedCategoriesIn,
  runningBalance,
  timelineMonths,
} from '@/core/timeline';
import type { Occurrence } from '@/core/series';

function occ(over: Partial<Occurrence> & { id: string; date: string }): Occurrence {
  return {
    ym: over.date.slice(0, 7),
    kind: 'expense',
    amountCents: 10_000,
    description: 'Gasto',
    categoryId: null,
    accountId: 'c6',
    transferAccountId: null,
    personId: 'eu',
    status: 'actual',
    rowId: over.id,
    seriesId: null,
    virtual: false,
    ...over,
  };
}

const CAIXA = new Set(['c6']);

describe('dueDateInMonth', () => {
  it('31 vira o último dia do mês', () => {
    expect(dueDateInMonth('2026-02', 31)).toBe('2026-02-28');
    expect(dueDateInMonth('2026-04', 31)).toBe('2026-04-30');
  });

  it('rejeita dia fora da faixa', () => {
    expect(() => dueDateInMonth('2026-08', 0)).toThrow();
    expect(() => dueDateInMonth('2026-08', 32)).toThrow();
  });
});

describe('occurrenceDelta', () => {
  it('entrada soma, saída subtrai', () => {
    expect(occurrenceDelta({ kind: 'income', amountCents: 500, accountId: 'c6' })).toBe(500);
    expect(occurrenceDelta({ kind: 'expense', amountCents: 500, accountId: 'c6' })).toBe(-500);
  });

  it('pagamento de fatura sai do caixa uma vez só', () => {
    // Destino é o cartão, que não guarda caixa: sai 3.400 e não volta nada.
    const delta = occurrenceDelta(
      { kind: 'transfer', amountCents: 340_000, accountId: 'c6' },
      CAIXA,
    );
    expect(delta).toBe(-340_000);
  });

  it('compra no cartão não mexe no caixa', () => {
    // Vira dívida hoje; o caixa só se mexe quando a fatura for paga. Contar os
    // dois seria pagar a mesma compra duas vezes.
    expect(
      occurrenceDelta(
        { kind: 'expense', amountCents: 5_000, accountId: 'cartao' },
        CAIXA,
      ),
    ).toBe(0);
    expect(
      occurrenceDelta(
        { kind: 'transfer', amountCents: 5_000, accountId: 'cartao' },
        CAIXA,
      ),
    ).toBe(0);
  });

  it('compra no cartão guarda o valor nominal, mesmo com caixa parado', () => {
    // Sem isso a lista mostraria "Terapia −R$ 0,00": verdade sobre o caixa,
    // mentira sobre o gasto.
    const [event] = buildTimelineEvents({
      occurrences: [
        occ({
          id: 'terapia',
          date: '2026-08-10',
          amountCents: 23_000,
          accountId: 'cartao',
        }),
      ],
      months: ['2026-08'],
      today: '2026-07-27',
      cashAccountIds: CAIXA,
    });

    expect(event!.deltaCents).toBe(0);
    expect(event!.nominalCents).toBe(-23_000);
    expect(event!.cashless).toBe(true);
  });

  it('gasto em conta de caixa não é cashless', () => {
    const [event] = buildTimelineEvents({
      occurrences: [occ({ id: 'a', date: '2026-08-10', amountCents: 5_000 })],
      months: ['2026-08'],
      today: '2026-07-27',
      cashAccountIds: CAIXA,
    });

    expect(event!.deltaCents).toBe(-5_000);
    expect(event!.nominalCents).toBe(-5_000);
    expect(event!.cashless).toBeFalsy();
  });

  it('estorno no cartão também não entra no caixa', () => {
    expect(
      occurrenceDelta(
        { kind: 'income', amountCents: 5_000, accountId: 'cartao' },
        CAIXA,
      ),
    ).toBe(0);
  });

  it('sem lista de contas de caixa, tudo conta', () => {
    // A lista é opcional: sem ela não há como saber o que é cartão.
    expect(
      occurrenceDelta({ kind: 'expense', amountCents: 5_000, accountId: 'x' }),
    ).toBe(-5_000);
  });
});

describe('buildTimelineEvents', () => {
  it('realizado e previsto viram eventos do mesmo tipo de linha', () => {
    const events = buildTimelineEvents({
      occurrences: [
        occ({ id: 'a', date: '2026-07-06', amountCents: 429_526 }),
        occ({
          id: 'virtual:sal:2026-07',
          date: '2026-07-31',
          kind: 'income',
          amountCents: 900_000,
          status: 'planned',
          rowId: null,
          seriesId: 'sal',
          virtual: true,
        }),
      ],
      months: ['2026-07'],
      today: '2026-07-27',
    });

    expect(events.map((e) => e.kind)).toEqual(['actual', 'planned']);
    expect(events[1]!.deltaCents).toBe(900_000);
    expect(events[1]!.virtual).toBe(true);
    expect(events[1]!.transactionId).toBeNull();
  });

  it('previsto com dia passado vem marcado como atraso', () => {
    const events = buildTimelineEvents({
      occurrences: [occ({ id: 'x', date: '2026-07-06', status: 'planned' })],
      months: ['2026-07'],
      today: '2026-07-27',
    });

    expect(events[0]!.overdue).toBe(true);
    expect(events[0]!.deltaCents).toBe(-10_000);
  });

  it('estimado entra proporcional no mês corrente e cheio nos futuros', () => {
    const events = buildTimelineEvents({
      occurrences: [],
      months: ['2026-06', '2026-07', '2026-08'],
      today: '2026-07-16', // faltam 15 dias dos 31
      forecastMonthlyCents: 310_000,
    });

    // Junho já fechou: história não recebe estimativa.
    // Datas no meio do restante / do mês — não no último dia após a renda.
    expect(events.map((e) => e.date)).toEqual(['2026-07-24', '2026-08-16']);
    expect(events[0]!.deltaCents).toBe(-150_000);
    expect(events[1]!.deltaCents).toBe(-310_000);
    expect(events.every((e) => e.estimated)).toBe(true);
  });

  it('sem estimativa não inventa evento', () => {
    const events = buildTimelineEvents({
      occurrences: [],
      months: ['2026-07'],
      today: '2026-07-16',
      forecastMonthlyCents: 0,
    });
    expect(events).toHaveLength(0);
  });

  it('mesmo dia: entrada antes de saída', () => {
    const events = buildTimelineEvents({
      occurrences: [
        occ({ id: 'saida', date: '2026-07-10', amountCents: 5_000 }),
        occ({ id: 'entrada', date: '2026-07-10', kind: 'income', amountCents: 5_000 }),
      ],
      months: ['2026-07'],
      today: '2026-07-27',
    });

    expect(events.map((e) => e.id)).toEqual(['entrada', 'saida']);
  });
});

describe('plannedCategoriesIn', () => {
  it('junta só categoria de despesa prevista', () => {
    const cats = plannedCategoriesIn([
      occ({ id: 'a', date: '2026-08-06', status: 'planned', categoryId: 'moradia' }),
      occ({ id: 'b', date: '2026-08-31', status: 'planned', kind: 'income', categoryId: 'salario' }),
      occ({ id: 'c', date: '2026-08-02', status: 'actual', categoryId: 'mercado' }),
    ]);

    expect([...cats]).toEqual(['moradia']);
  });
});

describe('runningBalance', () => {
  it('acumula a partir da âncora', () => {
    const events = buildTimelineEvents({
      occurrences: [
        occ({ id: 'a', date: '2026-07-02', amountCents: 1_000 }),
        occ({ id: 'b', date: '2026-07-03', kind: 'income', amountCents: 5_000 }),
      ],
      months: ['2026-07'],
      today: '2026-07-27',
    });

    expect(runningBalance(events, 10_000).map((p) => p.balanceCents)).toEqual([
      9_000, 14_000,
    ]);
  });
});

describe('groupTimeline', () => {
  const events = buildTimelineEvents({
    occurrences: [
      occ({ id: 'a', date: '2026-07-10', amountCents: 30_000 }),
      occ({ id: 'b', date: '2026-08-05', kind: 'income', amountCents: 100_000 }),
      occ({ id: 'c', date: '2026-08-20', amountCents: 25_000, status: 'planned' }),
    ],
    months: ['2026-07', '2026-08'],
    today: '2026-07-27',
  });

  const months = groupTimeline({
    events,
    anchorCents: 50_000,
    months: ['2026-07', '2026-08'],
  });

  it('abertura de um mês é o fechamento do anterior', () => {
    expect(months[0]!.closingCents).toBe(20_000);
    expect(months[1]!.openingCents).toBe(20_000);
  });

  it('resultado é entrou menos saiu, não o saldo', () => {
    expect(months[1]!.inCents).toBe(100_000);
    expect(months[1]!.outCents).toBe(25_000);
    expect(months[1]!.netCents).toBe(75_000);
    expect(months[1]!.closingCents).toBe(95_000);
  });

  it('marca o mês que tem previsto', () => {
    expect(months[0]!.hasPlanned).toBe(false);
    expect(months[1]!.hasPlanned).toBe(true);
  });

  it('dia sem evento não vira linha', () => {
    expect(months[0]!.days.map((d) => d.date)).toEqual(['2026-07-10']);
  });
});

describe('timelineMonths', () => {
  it('monta a janela em torno do mês corrente', () => {
    expect(timelineMonths('2026-07', 2, 2)).toEqual([
      '2026-05',
      '2026-06',
      '2026-07',
      '2026-08',
      '2026-09',
    ]);
  });
});

content.content:
1	/**
