import { MoneyText } from '@/components/money/MoneyText';
import { formatBRL } from '@/core/money';
import type { MonthMetrics } from '@/core/month-metrics';
import { PaceCompare } from '@/features/panel/components/PaceCompare';
import { cn } from '@/lib/cn';

type Phase = 'past' | 'current' | 'future';

type Props = {
  metrics: MonthMetrics;
  phase: Phase;
  minimumCents: number;
  comparison: { averageOutCents: number; deltaBps: number } | null;
};

function dayLabel(iso: string): string {
  return `dia ${Number(iso.slice(8, 10))}`;
}

/**
 * As perguntas que o extrato não responde.
 *
 * Escolhidas por decidirem alguma coisa: quanto ainda dá para gastar, quando o
 * saldo afunda, o que ainda vai sair. A grade muda com a fase do mês — e o
 * bloco “Por dia” junta ritmo, estimado e teto numa leitura só.
 */
export function MetricGrid({
  metrics: m,
  phase,
  minimumCents,
  comparison,
}: Props) {
  const tiles: React.ReactNode[] = [];
  // Sem colchão definido, "abaixo do mínimo" é só "no vermelho" — usar a
  // palavra do usuário evita a leitura de que existe um limite configurado.
  const hasCushion = minimumCents > 0;
  const belowWord = hasCushion ? 'abaixo do mínimo' : 'no vermelho';

  if (phase !== 'past' && m.freeToSpendCents != null) {
    const negative = m.freeToSpendCents < 0;
    tiles.push(
      <Tile
        key="free"
        label={
          negative
            ? hasCushion
              ? 'Falta para o colchão'
              : 'Vai faltar'
            : 'Livre para gastar'
        }
        tone={negative ? 'danger' : 'accent'}
        wide
        value={formatBRL(Math.abs(m.freeToSpendCents))}
        hint={
          negative
            ? `Mantendo o previsto, o saldo fica ${belowWord}${
                m.firstBelowMinimum ? ` no ${dayLabel(m.firstBelowMinimum)}` : ''
              }.`
            : m.safeDailyCents != null
              ? `${formatBRL(m.safeDailyCents)} por dia nos ${m.daysLeft} dias que faltam${hasCushion ? ', sem furar o colchão' : ''}.`
              : hasCushion
                ? 'Sem furar o colchão até o fim do mês.'
                : 'Até o fim do mês.'
        }
      />,
    );
  }

  tiles.push(<PaceCompare key="pace" metrics={m} phase={phase} />);

  if (m.lowest) {
    const target = phase === 'past' ? m.lowest : (m.lowestAhead ?? m.lowest);
    tiles.push(
      <Tile
        key="lowest"
        label={phase === 'past' ? 'Menor saldo do mês' : 'Menor saldo à frente'}
        tone={target.belowMinimum ? 'danger' : 'default'}
        value={formatBRL(target.balanceCents)}
        hint={
          target.belowMinimum
            ? hasCushion
              ? `${dayLabel(target.date)} · abaixo do colchão de ${formatBRL(minimumCents)}`
              : `${dayLabel(target.date)} · no vermelho`
            : dayLabel(target.date)
        }
      />,
    );
  }

  if (m.daysBelowMinimum > 0) {
    tiles.push(
      <Tile
        key="below"
        label={hasCushion ? 'Dias abaixo do colchão' : 'Dias no vermelho'}
        tone="danger"
        value={String(m.daysBelowMinimum)}
        hint={
          m.firstBelowMinimum
            ? `Começa no ${dayLabel(m.firstBelowMinimum)}`
            : undefined
        }
      />,
    );
  }

  if (phase !== 'past' && m.committedAheadCents > 0) {
    tiles.push(
      <Tile
        key="committed"
        label="Ainda vai sair"
        value={formatBRL(m.committedAheadCents)}
        hint="Contas e recorrências previstas"
      />,
    );
  }

  if (phase !== 'past' && m.estimatedAheadCents > 0) {
    tiles.push(
      <Tile
        key="estimated"
        label="Estimado à frente"
        value={formatBRL(m.estimatedAheadCents)}
        hint={
          m.estimatedDailyCents > 0
            ? `${formatBRL(m.estimatedDailyCents)}/dia · mediana fora do cadastrado`
            : 'Mediana do que você gasta fora do cadastrado'
        }
      />,
    );
  }

  if (phase !== 'past' && m.incomingAheadCents > 0) {
    tiles.push(
      <Tile
        key="incoming"
        label="Ainda vai entrar"
        tone="accent"
        value={formatBRL(m.incomingAheadCents)}
        hint={
          m.nextIncome
            ? `Próxima: ${m.nextIncome.label}, ${dayLabel(m.nextIncome.date)}`
            : undefined
        }
      />,
    );
  }

  // Ritmo solto só quando o bloco “Por dia” não montou (precisa de ≥2 células).
  const paceAlone =
    (phase === 'current' || phase === 'past') &&
    m.dailyBurnCents > 0 &&
    !(
      (phase !== 'past' && m.estimatedDailyCents > 0) ||
      (phase !== 'past' && m.safeDailyCents != null && m.safeDailyCents > 0)
    );

  if (paceAlone) {
    tiles.push(
      <Tile
        key="burn"
        label={phase === 'past' ? 'Média diária' : 'Ritmo de gasto'}
        value={`${formatBRL(m.dailyBurnCents)}/dia`}
        hint={
          phase === 'past'
            ? `Em ${m.elapsedDays} dias do mês`
            : m.safeDailyCents != null
              ? m.dailyBurnCents > m.safeDailyCents
                ? `Acima dos ${formatBRL(m.safeDailyCents)}/dia que cabem no resto do mês`
                : `Dentro dos ${formatBRL(m.safeDailyCents)}/dia que cabem`
              : `Média dos ${m.elapsedDays} dias já vividos`
        }
        tone={
          phase === 'current' &&
          m.safeDailyCents != null &&
          m.dailyBurnCents > m.safeDailyCents
            ? 'warning'
            : 'default'
        }
      />,
    );
  }

  if (m.burnRateBps != null) {
    const pct = m.burnRateBps / 100;
    tiles.push(
      <Tile
        key="burn-rate"
        label="Saídas ÷ entradas"
        value={`${pct.toFixed(0)}%`}
        hint={
          pct > 100
            ? 'Mês gastando mais do que entra'
            : 'Quanto da entrada do mês já virou saída'
        }
        tone={pct > 100 ? 'warning' : 'default'}
      />,
    );
  }

  if (m.overdueCount > 0) {
    tiles.push(
      <Tile
        key="overdue"
        label={m.overdueCount === 1 ? 'Conta atrasada' : 'Contas atrasadas'}
        tone="danger"
        value={formatBRL(m.overdueCents)}
        hint={`${m.overdueCount} ${m.overdueCount === 1 ? 'previsto venceu' : 'previstos venceram'} sem confirmação`}
      />,
    );
  }

  if (m.biggestExpense) {
    tiles.push(
      <Tile
        key="biggest"
        label="Maior saída"
        value={formatBRL(m.biggestExpense.cents)}
        hint={`${m.biggestExpense.label} · ${dayLabel(m.biggestExpense.date)}`}
      />,
    );
  }

  if (comparison) {
    const pct = comparison.deltaBps / 100;
    const worse = pct > 0;
    tiles.push(
      <Tile
        key="vs"
        label="Contra a média"
        tone={Math.abs(pct) < 5 ? 'default' : worse ? 'warning' : 'accent'}
        value={`${worse ? '+' : '−'}${Math.abs(pct).toFixed(0)}%`}
        hint={`Média de saída: ${formatBRL(comparison.averageOutCents)}`}
      />,
    );
  }

  const compositionTotal =
    m.fixedOutCents + m.variableOutCents + m.estimatedOutCents;

  if (tiles.length === 0 && compositionTotal <= 0) return null;

  return (
    <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
      {tiles}
      {compositionTotal > 0 ? (
        <OutflowComposition
          fixedCents={m.fixedOutCents}
          variableCents={m.variableOutCents}
          estimatedCents={m.estimatedOutCents}
        />
      ) : null}
    </div>
  );
}

function Tile({
  label,
  value,
  hint,
  tone = 'default',
  wide,
}: {
  label: string;
  value: string;
  hint?: string;
  tone?: 'default' | 'accent' | 'danger' | 'warning';
  wide?: boolean;
}) {
  return (
    <div
      className={cn(
        'rounded-xl border bg-surface p-3',
        wide && 'col-span-2 sm:col-span-3',
        tone === 'danger'
          ? 'border-danger/30'
          : tone === 'warning'
            ? 'border-warning/30'
            : tone === 'accent'
              ? 'border-accent/30'
              : 'border-border',
      )}
    >
      <p className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        {label}
      </p>
      <p
        className={cn(
          'mt-0.5 font-display tracking-tight tabular-nums',
          wide ? 'text-2xl font-semibold' : 'text-base font-medium',
          tone === 'danger'
            ? 'text-danger'
            : tone === 'warning'
              ? 'text-warning'
              : tone === 'accent'
                ? 'text-accent'
                : 'text-text',
        )}
      >
        {value}
      </p>
      {hint ? (
        <p className="mt-1 text-[11px] leading-snug text-text-muted">{hint}</p>
      ) : null}
    </div>
  );
}

/**
 * Composição da saída: recorrente, avulso e estimado. O estimado é mediana do
 * histórico — não é lançamento — então ganha fatia própria, não “avulso”.
 */
function OutflowComposition({
  fixedCents,
  variableCents,
  estimatedCents,
}: {
  fixedCents: number;
  variableCents: number;
  estimatedCents: number;
}) {
  const total = fixedCents + variableCents + estimatedCents;
  const fixedPct = Math.round((fixedCents / total) * 100);
  const variablePct = Math.round((variableCents / total) * 100);
  const estimatedPct = Math.max(0, 100 - fixedPct - variablePct);

  return (
    <div className="col-span-2 rounded-xl border border-border bg-surface p-3 sm:col-span-3">
      <p className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        Composição da saída
      </p>
      <div className="mt-2 flex h-2 gap-0.5 overflow-hidden rounded-full">
        {fixedCents > 0 ? (
          <div
            className="rounded-l-full bg-expense"
            style={{ width: `${fixedPct}%` }}
          />
        ) : null}
        {variableCents > 0 ? (
          <div className="bg-expense/55" style={{ width: `${variablePct}%` }} />
        ) : null}
        {estimatedCents > 0 ? (
          <div
            className="rounded-r-full bg-expense/25"
            style={{ width: `${estimatedPct}%` }}
          />
        ) : null}
      </div>
      <div className="mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 text-[11px]">
        <span className="text-text-muted">
          Recorrente{' '}
          <MoneyText cents={fixedCents} className="text-[11px] text-text" />{' '}
          <span className="font-mono tabular-nums">({fixedPct}%)</span>
        </span>
        {variableCents > 0 ? (
          <span className="text-text-muted">
            Avulso{' '}
            <MoneyText cents={variableCents} className="text-[11px] text-text" />{' '}
            <span className="font-mono tabular-nums">({variablePct}%)</span>
          </span>
        ) : null}
        {estimatedCents > 0 ? (
          <span className="text-text-muted">
            Estimado{' '}
            <MoneyText
              cents={estimatedCents}
              className="text-[11px] text-text"
            />{' '}
            <span className="font-mono tabular-nums">({estimatedPct}%)</span>
          </span>
        ) : null}
      </div>
    </div>
  );
}

