(async () => {
  window.__APIKEY = 'sb_publishable_RhwnAVt-PekkzGdI9lmA1g_VNzPxrqy';
  const tok = JSON.parse(localStorage.getItem('sb-zrqlbqevkpiejnmeqvax-auth-token')).access_token;
  const base = 'https://zrqlbqevkpiejnmeqvax.supabase.co/rest/v1';
  const q = async (p) => {
    const r = await fetch(base + p, { headers: { apikey: window.__APIKEY, Authorization: 'Bearer ' + tok } });
    return JSON.parse(await r.text());
  };
  window.__q2 = q;
  const accts = await q('/accounts?select=id,name,kind,person_id,archived');
  const cats = await q('/categories?select=id,name');
  const rows = await q('/transactions?select=id,date,kind,amount_cents,description,category_id,account_id,status,recurrence,series_id&date=gte.2026-07-01&date=lte.2026-07-31&status=eq.actual&order=date');
  const catName = Object.fromEntries(cats.map(c => [c.id, c.name]));
  const acctById = Object.fromEntries(accts.map(a => [a.id, a]));
  const cash = new Set(accts.filter(a => a.kind !== 'credit').map(a => a.id));
  const out = rows.filter(r => r.kind !== 'income' && cash.has(r.account_id));
  const total = out.reduce((s, r) => s + r.amount_cents, 0);
  return {
    accts: accts.map(a => `${a.name}|${a.kind}|${a.person_id ? 'p' : '-'}`),
    total, dias: 28, media: Math.round(total / 28),
    linhas: out.map(r => [r.date, r.kind, (r.amount_cents/100).toFixed(2), r.description, catName[r.category_id] || '—', acctById[r.account_id]?.name, r.series_id ? 'serie' : 'avulso'].join(' | ')),
  };
})()

