  recurrence: TransactionRecurrence;
  /** Último dia em que a série ocorre. Null = indefinidamente. */
  recurrenceEnd: string | null;
  /** Exceção de um mês: aponta para a linha-modelo da série. */
  seriesId: TransactionId | null;
  notes: string | null;
