(async () => {
  const accts = await window.__q2('/accounts?select=id,name,kind');
  const byId = Object.fromEntries(accts.map(a => [a.id, a]));
  const credit = accts.filter(a => a.kind === 'credit').map(a => a.id);
  const rows = await window.__q2('/transactions?select=date,kind,amount_cents,description,account_id,status,recurrence,series_id&account_id=in.(' + credit.join(',') + ')&order=date');
  return rows.map(r => [r.date, byId[r.account_id].name, r.kind, (r.amount_cents/100).toFixed(2), r.description, r.status, r.recurrence, r.series_id ? 'exc' : ''].join(' | '));
})()

