        if (isForecast) estimatedAheadCents += abs;
        else committedAheadCents += abs;
      } else {
        incomingAheadCents += event.deltaCents;
      }
    }

    if (event.deltaCents > 0 && future && !nextIncome) {
      nextIncome = {
        label: event.label,
        cents: event.deltaCents,
        date: event.date,
      };
    }
  }

