  month: TimelineMonth,
  closedMonths: ReadonlyArray<TimelineMonth>,
): { averageOutCents: number; deltaBps: number } | null {
  const others = closedMonths.filter(
    (m) =>
      m.ym !== month.ym &&
      m.days.length > 0 &&
      monthCoverage(
        m.ym,
