/**
 * Composição da saída, pela mesma régua do ritmo.
 *
 * “Recorrente × avulso” classificava por `series_id`, então o aluguel de julho —
 * importado do extrato, sem série — caía em “avulso” e a tela ensinava que
 * R$ 4.295 de moradia eram gasto solto. Aqui o corte é o mesmo do ritmo:
 * compromisso, fatura, variável, estimado.
 *
 * A fatura é fatia própria porque é opaca: R$ 3.400 de compras que ninguém
 * lançou uma por uma. Enquanto ela existir, essa parte do mês é uma caixa
 * fechada — importar o extrato do cartão a dissolve nas outras três.
 */
function OutflowComposition({
  fixedCents,
  settlementCents,
  variableCents,
  estimatedCents,
}: {
  fixedCents: number;
  settlementCents: number;
  variableCents: number;
  estimatedCents: number;
}) {
  const total = fixedCents + settlementCents + variableCents + estimatedCents;

  const slices = [
    { key: 'fixed', label: 'Compromisso', cents: fixedCents, fill: 'bg-expense' },
    { key: 'settlement', label: 'Fatura', cents: settlementCents, fill: 'bg-expense/60' },
    { key: 'variable', label: 'Variável', cents: variableCents, fill: 'bg-expense/35' },
    { key: 'estimated', label: 'Estimado', cents: estimatedCents, fill: 'bg-expense/18' },
  ].filter((s) => s.cents > 0);

  // O resto fecha a conta em 100 sem arredondar duas vezes para o mesmo lado.
  let used = 0;
  const withPct = slices.map((s, i) => {
    const pct =
      i === slices.length - 1
        ? Math.max(0, 100 - used)
        : Math.round((s.cents / total) * 100);
    used += pct;
    return { ...s, pct };
  });

  return (
    <div className="col-span-2 rounded-xl border border-border bg-surface p-3 sm:col-span-3">
      <p className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        Composição da saída
      </p>
      <div className="mt-2 flex h-2.5 gap-0.5 overflow-hidden rounded-full">
        {withPct.map((s, i) => (
          <div
            key={s.key}
            className={cn(
              s.fill,
              i === 0 && 'rounded-l-full',
              i === withPct.length - 1 && 'rounded-r-full',
            )}
            style={{ width: `${s.pct}%` }}
          />
        ))}
      </div>
      <div className="mt-2 flex flex-wrap items-baseline gap-x-4 gap-y-1 text-[11px]">
        {withPct.map((s) => (
          <span key={s.key} className="text-text-muted">
            {s.label}{' '}
            <MoneyText cents={s.cents} className="text-[11px] text-text" />{' '}
            <span className="font-mono tabular-nums">({s.pct}%)</span>
          </span>
        ))}
      </div>
    </div>
  );
}

