1	import { formatBRL } from '@/core/money';
2	import type { MonthMetrics } from '@/core/month-metrics';
3	import { cn } from '@/lib/cn';
4	
5	type Phase = 'past' | 'current' | 'future';
6	
7	type Props = {
8	  metrics: MonthMetrics;
9	  phase: Phase;
10	  /** No herói não usa col-span do grid de métricas. */
11	  layout?: 'grid' | 'stack';
12	};
13	
14	type PaceCell = {
15	  key: string;
16	  label: string;
17	  cents: number;
18	  hint: string;
19	  tone: 'default' | 'accent' | 'warning' | 'danger';
20	};
21	
22	/**
23	 * Três leituras do mesmo dia: o que você vem gastando, o que o histórico
24	 * espera, e o que o caixa ainda aguenta. Uma grade de tiles soltos escondia
25	 * a comparação — aqui os três ficam lado a lado.
26	 *
27	 * As três células só são comparáveis porque todas falam de **variável**: o
28	 * ritmo ignora compromisso e fatura, o estimado é mediana do que não está
29	 * cadastrado, e o "cabe por dia" já nasce depois de descontar as contas. Quando
30	 * o ritmo somava aluguel, o veredito acusava excesso em todo mês.
31	 */
32	export function PaceCompare({ metrics: m, phase, layout = 'grid' }: Props) {
33	  const cells: PaceCell[] = [];
34	
35	  if (phase === 'current' && m.dailyBurnCents > 0) {
36	    const overSafe =
37	      m.safeDailyCents != null && m.dailyBurnCents > m.safeDailyCents;
38	    const overEst =
39	      m.estimatedDailyCents > 0 && m.dailyBurnCents > m.estimatedDailyCents;
40	    cells.push({
41	      key: 'burn',
42	      label: 'Ritmo até hoje',
43	      cents: m.dailyBurnCents,
44	      hint: `${formatBRL(m.realizedVariableCents)} em ${m.elapsedDays} ${m.elapsedDays === 1 ? 'dia' : 'dias'}`,
45	      tone: overSafe ? 'warning' : overEst ? 'warning' : 'default',
46	    });
47	  }
48	
49	  if (phase === 'past' && m.dailyBurnCents > 0) {
50	    cells.push({
51	      key: 'burn',
52	      label: 'Média do mês',
53	      cents: m.dailyBurnCents,
54	      hint: `${formatBRL(m.realizedVariableCents)} em ${m.elapsedDays} dias`,
55	      tone: 'default',
56	    });
57	  }
58	
59	  if (phase !== 'past' && m.estimatedDailyCents > 0) {
60	    cells.push({
61	      key: 'estimated',
62	      label: phase === 'current' ? 'Estimado à frente' : 'Estimado / dia',
63	      cents: m.estimatedDailyCents,
64	      hint:
65	        phase === 'current'
66	          ? `Variável nos ${m.daysAhead} dias que faltam`
67	          : 'Mediana histórica diluída no mês',
68	      tone: 'default',
69	    });
70	  }
71	
72	  if (phase !== 'past' && m.safeDailyCents != null && m.safeDailyCents > 0) {
73	    cells.push({
74	      key: 'safe',
75	      label: 'Cabe por dia',
76	      cents: m.safeDailyCents,
77	      hint: `${m.daysLeft} ${m.daysLeft === 1 ? 'dia' : 'dias'} sem furar o colchão`,
78	      tone: 'accent',
79	    });
80	  }
81	
82	  // No stack (herói) um único número ainda vale a pena; no grid antigo, não.
83	  if (cells.length === 0) return null;
84	  if (layout === 'grid' && cells.length < 2) return null;
85	
86	  const verdict = paceVerdict(m, phase);
87	
88	  return (
89	    <div
90	      className={cn(
91	        'rounded-xl border border-border bg-surface p-3',
92	        layout === 'grid' && 'col-span-2 sm:col-span-3',
93	      )}
94	    >
95	      <p className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
96	        Por dia · só o variável
97	      </p>
98	      <div
99	        className={cn(
100	          'mt-2 grid gap-3',
101	          cells.length === 1
102	            ? 'grid-cols-1'
103	            : cells.length === 2
104	              ? 'grid-cols-2'
105	              : 'grid-cols-3',
106	        )}
107	      >
108	        {cells.map((cell) => (
109	          <div key={cell.key} className="min-w-0">
110	            <p className="text-[11px] text-text-muted">{cell.label}</p>
111	            <p
112	              className={cn(
113	                'mt-0.5 font-display text-base font-medium tracking-tight tabular-nums',
114	                cell.tone === 'warning'
115	                  ? 'text-warning'
116	                  : cell.tone === 'accent'
117	                    ? 'text-accent'
118	                    : cell.tone === 'danger'
119	                      ? 'text-danger'
120	                      : 'text-text',
121	              )}
122	            >
123	              {formatBRL(cell.cents)}
124	              <span className="text-[11px] font-sans font-normal text-text-muted">
125	                /dia
126	              </span>
127	            </p>
128	            <p className="mt-0.5 text-[10px] leading-snug text-text-muted">
129	              {cell.hint}
130	            </p>
131	          </div>
132	        ))}
133	      </div>
134	      {verdict || m.realizedCommittedCents > 0 ? (
135	        <div className="mt-2.5 space-y-1 border-t border-border/70 pt-2">
136	          {verdict ? (
137	            <p
138	              className={cn(
139	                'text-[11px] leading-snug',
140	                verdict.tone === 'warning'
141	                  ? 'text-warning'
142	                  : verdict.tone === 'accent'
143	                    ? 'text-accent'
144	                    : 'text-text-muted',
145	              )}
146	            >
147	              {verdict.text}
148	            </p>
149	          ) : null}
150	          {m.realizedCommittedCents > 0 ? (
151	            <p className="text-[10px] leading-snug text-text-muted">
152	              Fora do ritmo: {formatBRL(m.realizedCommittedCents)} de
153	              compromisso já pago no mês — recorrências, contas essenciais e
154	              fatura. Não se decide por dia, então não vira média diária.
155	            </p>
156	          ) : null}
157	        </div>
158	      ) : null}
159	    </div>
160	  );
161	}
162	
163	function paceVerdict(
164	  m: MonthMetrics,
165	  phase: Phase,
166	): { text: string; tone: 'default' | 'accent' | 'warning' } | null {
167	  if (phase !== 'current') return null;
168	
169	  const burn = m.dailyBurnCents;
170	  const safe = m.safeDailyCents;
171	  const est = m.estimatedDailyCents;
172	
173	  if (burn <= 0) return null;
174	
175	  if (
176	    m.headroomBurnDays != null &&
177	    m.paceGapCents != null &&
178	    m.paceGapCents > 0
179	  ) {
180	    return {
181	      tone: 'warning',
182	      text: `Ritmo ${formatBRL(m.paceGapCents)}/dia acima do estimado — a folga aguenta ~${m.headroomBurnDays} ${m.headroomBurnDays === 1 ? 'dia' : 'dias'} se mantiver.`,
183	    };
184	  }
185	
186	  if (safe != null && burn > safe) {
187	    return {
188	      tone: 'warning',
189	      text: `Ritmo acima do que cabe — se mantiver, o colchão aperta antes do fim do mês.`,
190	    };
191	  }
192	
193	  if (est > 0 && burn > est) {
194	    return {
195	      tone: 'warning',
196	      text: `Ritmo acima do estimado histórico (${formatBRL(est)}/dia). Mês mais caro que o habitual.`,
197	    };
198	  }
199	
200	  if (est > 0 && burn > 0 && burn <= est) {
201	    return {
202	      tone: 'accent',
203	      text: `No ritmo do estimado; o livre é folga além do que o histórico já prevê.`,
204	    };
205	  }
206	
207	  if (safe != null && burn > 0 && burn <= safe) {
208	    return {
209	      tone: 'default',
210	      text: `Dentro do que cabe nos ${m.daysLeft} dias que faltam.`,
211	    };
212	  }
213	
214	  return null;
215	}

