1	/**
2	 * Previsão de gasto variável a partir do histórico.
3	 *
4	 * O plano só cobre o que você lembrou de cadastrar. Mercado, farmácia e PIX
5	 * miúdo nunca entram — e são a maior parte do gasto. Sem isso a projeção fica
6	 * otimista pelo valor inteiro do variável, todo mês.
7	 *
8	 * Duas defesas contra número inventado:
9	 *
10	 * 1. **Categoria coberta pelo plano não é prevista pelo histórico.** Aluguel
11	 *    tem item no plano, então Moradia sai daqui — senão conta duas vezes.
12	 * 2. **Mês incompleto ou é descartado ou é normalizado.** Um extrato que só
13	 *    cobre 6 dias de junho não vale como "mês de junho"; usá-lo cru puxaria a
14	 *    média para baixo e a projeção voltaria a mentir, só que para o outro lado.
15	 *
16	 * A saída é uma faixa (menor mês / maior mês), não um número exato: com
17	 * poucos meses de histórico, precisão falsa é pior que uma faixa honesta.
18	 */
19	
20	import { getDaysInMonth } from 'date-fns';
21	import { assertYearMonth, type YearMonth } from '@/core/month';
22	
23	export type ForecastTx = {
24	  /** ISO yyyy-MM-dd. */
25	  date: string;
26	  kind: 'income' | 'expense' | 'transfer';
27	  amountCents: number;
28	  categoryId: string | null;
29	};
30	
31	export type CategoryForecast = {
32	  categoryId: string | null;
33	  /** Mediana dos meses usados, normalizada para mês cheio. */
34	  monthlyCents: number;
35	  lowCents: number;
36	  highCents: number;
37	  monthsUsed: number;
38	};
39	
40	export type SkippedMonth = {
41	  ym: YearMonth;
42	  reason: 'no_data' | 'low_coverage';
43	  /** Fração do mês com dados (0–1). */
44	  coverage: number;
45	};
46	
47	export type VariableForecast = {
48	  /** Soma das medianas por categoria. */
49	  totalMonthlyCents: number;
50	  lowCents: number;
51	  highCents: number;
52	  byCategory: CategoryForecast[];
53	  monthsUsed: YearMonth[];
54	  monthsSkipped: SkippedMonth[];
55	  /** `none` sem histórico usável; `low` com 1–2 meses. */
56	  confidence: 'none' | 'low' | 'medium';
57	};
58	
59	const DEFAULT_MIN_COVERAGE = 0.8;
60	
61	/** Fração do mês coberta pelos lançamentos (primeiro ao último dia visto). */
62	export function monthCoverage(ym: string, dates: ReadonlyArray<string>): number {
63	  assertYearMonth(ym);
64	  const inMonth = dates.filter((d) => d.slice(0, 7) === ym).sort();
65	  if (inMonth.length === 0) return 0;
66	
67	  const [y, m] = ym.split('-').map(Number);
68	  const dim = getDaysInMonth(new Date(y!, m! - 1, 1));
69	  const first = Number(inMonth[0]!.slice(8, 10));
70	  const last = Number(inMonth[inMonth.length - 1]!.slice(8, 10));
71	  return (last - first + 1) / dim;
72	}
73	
74	function median(values: number[]): number {
75	  if (values.length === 0) return 0;
76	  const sorted = [...values].sort((a, b) => a - b);
77	  const mid = Math.floor(sorted.length / 2);
78	  if (sorted.length % 2 === 1) return sorted[mid]!;
79	  return Math.round((sorted[mid - 1]! + sorted[mid]!) / 2);
80	}
81	
82	/**
83	 * Estima o gasto variável mensal por categoria.
84	 *
85	 * `plannedCategoryIds` = categorias que já têm item ativo no plano.
86	 */
87	export function forecastVariable(input: {
88	  transactions: ReadonlyArray<ForecastTx>;
89	  /** Meses de histórico a considerar. */
90	  months: ReadonlyArray<YearMonth>;
91	  plannedCategoryIds?: ReadonlySet<string | null> | null;
92	  /** Cobertura mínima para o mês contar. Padrão 0.8. */
93	  minCoverage?: number;
