  window.__APIKEY = 'sb_publishable_RhwnAVt-PekkzGdI9lmA1g_VNzPxrqy';
  const tok = JSON.parse(localStorage.getItem('sb-zrqlbqevkpiejnmeqvax-auth-token')).access_token;
  const base = 'https://zrqlbqevkpiejnmeqvax.supabase.co/rest/v1';
  const q = async (p) => JSON.parse(await (await fetch(base + p, { headers: { apikey: window.__APIKEY, Authorization: 'Bearer ' + tok } })).text());
  const accts = await q('/accounts?select=id,name,kind,person_id');
  const eu = accts.filter(a => a.kind !== 'credit' && (a.person_id == null || a.name === 'c6'));
  const cash = new Set(eu.map(a => a.id));
  const rows = await q('/transactions?select=date,kind,amount_cents,description,account_id,status,recurrence,series_id&date=gte.2026-08-01&date=lte.2026-08-31&order=date');
  const ev = rows.filter(r => r.recurrence === 'none' && cash.has(r.account_id))
    .map(r => ({ d: Number(r.date.slice(8,10)), delta: r.kind === 'income' ? r.amount_cents : -r.amount_cents, l: r.description }));
  // séries mensais (templates) que caem em agosto
  const tpl = (await q('/transactions?select=date,kind,amount_cents,description,account_id,recurrence,recurrence_end&recurrence=eq.monthly'))
    .filter(t => cash.has(t.account_id) && t.date.slice(0,7) <= '2026-08' && (!t.recurrence_end || t.recurrence_end >= '2026-08-01'))
    .map(t => ({ d: Number(t.date.slice(8,10)), delta: t.kind === 'income' ? t.amount_cents : -t.amount_cents, l: t.description + ' ↻' }));
  const all = [...ev, ...tpl].sort((a,b) => a.d - b.d);
  let bal = 958479; const daily = [];
  for (let d = 1; d <= 31; d++) {
    for (const e of all.filter(e => e.d === d)) bal += e.delta;
    daily.push({ d, bal });
  }
  const DRIP = 13112;
  let bal2 = 958479; const dripSeries = [];
  for (let d = 1; d <= 31; d++) {
    for (const e of all.filter(e => e.d === d)) bal2 += e.delta;
    bal2 -= DRIP;
    dripSeries.push({ d, bal: bal2 });
  }
  const lo = daily.reduce((a,b) => b.bal < a.bal ? b : a);
  const lo2 = dripSeries.reduce((a,b) => b.bal < a.bal ? b : a);
  return {
    eventos: all.map(e => `${e.d} ${(e.delta/100).toFixed(2)} ${e.l}`),
    hoje_menor: `dia ${lo.d} = ${(lo.bal/100).toFixed(2)}`,
    com_drip_menor: `dia ${lo2.d} = ${(lo2.bal/100).toFixed(2)}`,
    fecha_hoje: (daily[30].bal/100).toFixed(2),
    fecha_drip: (dripSeries[30].bal/100).toFixed(2),
    curva_hoje: daily.map(p => Math.round(p.bal/100)),
    curva_drip: dripSeries.map(p => Math.round(p.bal/100)),
  };
})()

