import type { DayPoint } from '@/core/month-metrics';
import type { TimelineMonth } from '@/core/timeline';
import { BalanceByDayChart } from '@/features/panel/components/BalanceByDayChart';
import { MinimumControl } from '@/features/panel/components/MinimumControl';
import { MonthDashboard } from '@/features/panel/components/MonthDashboard';

type Props = {
  month: TimelineMonth;
  points: DayPoint[];
  minimumCents: number;
  lowest: DayPoint | null;
  isCurrent: boolean;
  isFuture: boolean;
  onSelectDay?: (date: string) => void;
};

/**
 * Trajetória do caixa: curva + colchão + abriu/fecha.
 *
 * Uma seção só — a prova visual de por que o herói é aquele número.
 */
export function TrajectorySection({
  month,
  points,
  minimumCents,
  lowest,
  isCurrent,
  isFuture,
  onSelectDay,
}: Props) {
  return (
    <section className="space-y-2">
      <p className="px-1 font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        Como o saldo caminha
      </p>
      <BalanceByDayChart
        points={points}
        minimumCents={minimumCents}
        lowest={lowest}
        onSelectDay={onSelectDay}
      />
      <MinimumControl cents={minimumCents} />
      <MonthDashboard
        month={month}
        isCurrent={isCurrent}
        isFuture={isFuture}
      />
    </section>
  );
}

