14	  trajectory: Trajectory;
15	  minimumCents: number;
16	  currentYm: string;
17	  onSelect?: (ym: string) => void;
18	};
19	
20	function short(cents: number): string {
21	  const v = cents / 100;
22	  const sign = v < 0 ? '−' : '';
23	  const abs = Math.abs(v);
24	  if (abs >= 1000) return `${sign}${(abs / 1000).toFixed(0)}k`;
25	  return `${sign}${Math.round(abs)}`;
26	}
27	
28	/**
29	 * Onde o saldo chega ao longo da janela.
30	 *
31	 * A fita mostra deltas por mês; deltas não somam de cabeça. Doze resultados
32	 * positivos em sequência não dizem se o saldo dobrou ou ficou parado — o olho
33	 * não acumula. Esta curva é a mesma informação, acumulada, e responde a pergunta
34	 * que a fita não responde: “estou construindo algo?”.
35	 *
36	 * Fato e projeção se separam por **traço**, como no gráfico do mês. Uma subida
37	 * reta e longa aqui é sinal de otimismo na projeção, não de riqueza — e é bom
38	 * que fique óbvio em vez de enterrado num aviso.
39	 */
40	export function TrajectoryChart({
41	  trajectory: t,
42	  minimumCents,
43	  currentYm,
44	  onSelect,
45	}: Props) {
46	  const points = t.points;
47	  if (points.length < 2) return null;
48	
49	  const values = points.map((p) => p.closingCents);
50	  const rawMin = Math.min(...values, minimumCents, 0);
51	  const rawMax = Math.max(...values, minimumCents, 0);
52	  const span = Math.max(rawMax - rawMin, 1);
53	  const min = rawMin - span * 0.14;
54	  const max = rawMax + span * 0.14;
55	
56	  const plotW = W - PAD_L - PAD_R;
57	  const plotH = H - PAD_T - PAD_B;
58	
59	  const x = (i: number) => PAD_L + (i / (points.length - 1)) * plotW;
60	  const y = (cents: number) =>
61	    PAD_T + plotH - ((cents - min) / (max - min)) * plotH;
62	
63	  const currentIndex = points.findIndex((p) => p.ym === currentYm);
64	  const splitAt = currentIndex >= 0 ? currentIndex : 0;
65	
66	  const path = (from: number, to: number) =>
67	    points
68	      .slice(from, to + 1)
69	      .map((p, k) => `${k === 0 ? 'M' : 'L'}${x(from + k)},${y(p.closingCents)}`)
70	      .join(' ');
71	
72	  const yMin = y(minimumCents);
73	  const showMinimum = minimumCents > 0;
74	  const growing = t.deltaCents >= 0;
75	  const spansYears = points[0]!.ym.slice(0, 4) !== points.at(-1)!.ym.slice(0, 4);
76	
77	  return (
78	    <figure className="overflow-hidden rounded-xl border border-border bg-surface">
79	      <figcaption className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 border-b border-border px-4 py-3">
80	        <h3 className="font-mono text-[10px] uppercase tracking-[0.12em] text-text-muted">
81	          Para onde o saldo caminha
82	        </h3>
83	        <p className="text-[11px] tabular-nums text-text-muted">
84	          {formatMonth(points.at(-1)!.ym, 'MMM yyyy')}{' '}
85	          <span className="text-text">{formatBRL(t.endCents)}</span>{' '}
86	          <span className={growing ? 'text-accent' : 'text-danger'}>
87	            {growing ? '+' : '−'}
88	            {short(Math.abs(t.deltaCents))}
89	          </span>
90	        </p>
91	      </figcaption>
92	
93	      <div className="px-2 pb-1 pt-1 sm:px-3">
94	        <svg
95	          viewBox={`0 0 ${W} ${H}`}
96	          className="w-full"
97	          style={{ height: 'auto' }}
98	          role="img"
99	          aria-label={`Saldo de fechamento por mês, de ${points[0]!.ym} a ${points.at(-1)!.ym}. Termina em ${formatBRL(t.endCents)}.`}
100	        >
101	          {[rawMin, rawMax].map((tick) => (
102	            <g key={tick}>
103	              <line
104	                x1={PAD_L}
105	                x2={W - PAD_R}
106	                y1={y(tick)}
107	                y2={y(tick)}
108	                className="stroke-border/70"
109	                strokeWidth={1}
110	              />
111	              <text
112	                x={PAD_L - 8}
113	                y={y(tick) + 3}
114	                textAnchor="end"
115	                className="fill-text-muted font-mono text-[11px]"
116	              >
117	                {short(tick)}
118	              </text>
119	            </g>
120	          ))}
121	
122	          {showMinimum && yMin > PAD_T && yMin < PAD_T + plotH ? (
123	            <line
124	              x1={PAD_L}
125	              x2={W - PAD_R}
126	              y1={yMin}
127	              y2={yMin}
128	              className="stroke-danger/50"
129	              strokeWidth={1}
130	              strokeDasharray="3 3"
131	            />
132	          ) : null}
133	
134	          {splitAt > 0 ? (
135	            <path
136	              d={path(0, splitAt)}
137	              fill="none"
138	              className="stroke-accent"
139	              strokeWidth={2}
140	              strokeLinejoin="round"
141	              strokeLinecap="round"
142	            />
143	          ) : null}
144	
145	          <path
146	            d={path(splitAt, points.length - 1)}
147	            fill="none"
148	            className="stroke-text-muted"
149	            strokeWidth={2}
150	            strokeDasharray="5 4"
151	            strokeLinejoin="round"
152	            strokeLinecap="round"
153	            opacity={0.85}
154	          />
155	
156	          {points.map((p, i) => (
157	            <g key={p.ym}>
158	              {onSelect ? (
159	                <rect
160	                  x={x(i) - plotW / (points.length * 2)}
161	                  y={PAD_T}
162	                  width={plotW / points.length}
163	                  height={plotH}
164	                  fill="transparent"
165	                  className="cursor-pointer"
166	                  onClick={() => onSelect(p.ym)}
167	                >
168	                  <title>
169	                    {formatMonth(p.ym, 'MMMM yyyy')} · {formatBRL(p.closingCents)}
170	                  </title>
171	                </rect>
172	              ) : null}
173	              {p.belowMinimum || p.ym === t.lowest?.ym ? (
174	                <circle
175	                  cx={x(i)}
176	                  cy={y(p.closingCents)}
177	                  r={3.5}
178	                  className={cn(
179	                    'stroke-surface',
180	                    p.belowMinimum ? 'fill-danger' : 'fill-text-muted',
181	                  )}
182	                  strokeWidth={2}
183	                />
184	              ) : null}
185	            </g>
186	          ))}
187	
188	          {/* Só as pontas e o mês corrente: doze rótulos colidem. Com ano, porque
189	              a janela cruza o réveillon e dois "jul" lado a lado não se distinguem. */}
190	          {[0, splitAt, points.length - 1]
191	            .filter((i, k, arr) => arr.indexOf(i) === k)
192	            .map((i) => (
193	              <text
194	                key={i}
195	                x={Math.min(Math.max(x(i), PAD_L + 20), W - PAD_R - 20)}
196	                y={H - 8}
197	                textAnchor="middle"
198	                className={cn(
199	                  'font-mono text-[11px]',
200	                  i === splitAt ? 'fill-text' : 'fill-text-muted',
201	                )}
202	              >
203	                {formatMonth(points[i]!.ym, spansYears ? 'MMM/yy' : 'MMM')}
204	              </text>
205	            ))}
206	        </svg>
207	      </div>
208	
209	      {t.lowest && t.lowest.closingCents < minimumCents ? (
210	        <p className="border-t border-border px-4 py-2.5 text-[11px] leading-snug text-danger">
211	          O pior fechamento à frente é{' '}
212	          <span className="font-medium tabular-nums">
213	            {formatBRL(t.lowest.closingCents)}
214	          </span>{' '}
215	          em {formatMonth(t.lowest.ym, 'MMMM yyyy')} — abaixo do colchão.
216	        </p>
217	      ) : null}
218	    </figure>
219	  );
220	}

