import { MoneyText } from '@/components/money/MoneyText';
import type { TimelineMonth } from '@/core/timeline';
import { cn } from '@/lib/cn';

type Props = {
  month: TimelineMonth;
  isCurrent: boolean;
  isFuture: boolean;
};

/**
 * O mês em números.
 *
 * Abriu e fecha são **saldo**; entrou, saiu e resultado são **fluxo**. Misturar
 * os dois no mesmo rótulo foi o que fez o painel parecer contraditório — "sobra
 * −2.990" ao lado de "5.104" eram os dois certos, com nome enganoso. Aqui a
 * distinção é a própria estrutura: saldo na linha de cima, fluxo embaixo.
 *
 * “Saiu” é só lançamento (realizado/previsto). O estimado do histórico aparece
 * à parte — senão mês futuro parece ter R$ 8k de conta cadastrada.
 */
export function MonthDashboard({ month, isCurrent, isFuture }: Props) {
  const negative = month.netCents < 0;
  const closingNegative = month.closingCents < 0;
  const hasEstimate = month.estimatedOutCents > 0;

  return (
    <section className="rounded-xl border border-border bg-surface">
      {/* Em 375px a régua no meio empurrava o "fecha com" para fora da tela;
          no mobile ela desce para a própria linha. */}
      <div className="px-4 pt-4">
        <div className="flex items-start justify-between gap-3">
          <Anchor label="Abriu com" cents={month.openingCents} />
          <div className="hidden flex-1 items-center pt-4 sm:flex">
            <span className="h-px flex-1 bg-border-strong" />
            <Delta negative={negative} cents={month.netCents} />
            <span className="h-px flex-1 bg-border-strong" />
          </div>
          <Anchor
            label={isFuture || isCurrent ? 'Fecha com' : 'Fechou com'}
            cents={month.closingCents}
            align="right"
            danger={closingNegative}
            emphasis
          />
        </div>
        <div className="mt-3 flex items-center sm:hidden">
          <span className="h-px flex-1 bg-border-strong" />
          <Delta negative={negative} cents={month.netCents} />
          <span className="h-px flex-1 bg-border-strong" />
        </div>
      </div>

      <dl
        className={cn(
          'mt-4 grid border-t border-border',
          hasEstimate ? 'grid-cols-2 sm:grid-cols-4' : 'grid-cols-3',
        )}
      >
        <Cell label="Entrou">
          <MoneyText
            cents={month.inCents}
            tone="income"
            className="text-sm tabular-nums"
          />
        </Cell>
        <Cell label="Saiu" divider>
          <MoneyText
            cents={month.bookedOutCents}
            className="text-sm tabular-nums"
          />
        </Cell>
        {hasEstimate ? (
          <Cell label="Estimado" divider>
            <MoneyText
              cents={month.estimatedOutCents}
              className="text-sm tabular-nums text-text-muted"
            />
          </Cell>
        ) : null}
        <Cell label="Resultado" divider>
          <MoneyText
            cents={month.netCents}
            signed
            tone={negative ? 'danger' : 'income'}
            className="text-sm font-semibold tabular-nums"
          />
        </Cell>
      </dl>
    </section>
  );
}

function Delta({ negative, cents }: { negative: boolean; cents: number }) {
  return (
    <span
      className={cn(
        'mx-2 whitespace-nowrap rounded-full border px-2 py-0.5 font-mono text-[10px] uppercase tracking-[0.08em]',
        negative
          ? 'border-danger/40 bg-danger/10 text-danger'
          : 'border-accent/40 bg-accent-muted text-accent',
      )}
    >
      {negative ? 'queimou' : 'sobrou'} {formatShort(Math.abs(cents))}
    </span>
  );
}

function Anchor({
  label,
  cents,
  align,
  danger,
  emphasis,
}: {
  label: string;
  cents: number;
  align?: 'right';
  danger?: boolean;
  emphasis?: boolean;
}) {
  return (
    <div className={cn('min-w-0', align === 'right' && 'text-right')}>
      <p className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        {label}
      </p>
      <p
        className={cn(
          'truncate font-display tracking-tight tabular-nums',
          emphasis ? 'text-lg font-semibold sm:text-xl' : 'text-lg',
        )}
      >
        <MoneyText cents={cents} tone={danger ? 'danger' : 'default'} />
      </p>
    </div>
  );
}

function Cell({
  label,
  children,
  divider,
}: {
  label: string;
  children: React.ReactNode;
  divider?: boolean;
}) {
  return (
    <div className={cn('px-4 py-3', divider && 'border-l border-border')}>
      <dt className="font-mono text-[10px] uppercase tracking-[0.1em] text-text-muted">
        {label}
      </dt>
      <dd className="mt-0.5">{children}</dd>
    </div>
  );
}

function formatShort(cents: number): string {
  return (cents / 100).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL',
    maximumFractionDigits: 0,
  });
}

