3	import { formatBRL } from '@/core/money';
4	import type { MerchantGroup } from '@/core/transactions/grouping';
5	import { useBulkCategorize } from '@/features/panel/hooks/useBulkCategorize';
6	import { cn } from '@/lib/cn';
7	
8	type Props = {
9	  groups: MerchantGroup[];
10	  /** Total sem categoria no mês, para dar tamanho ao problema. */
11	  totalCents: number;
12	  /**
13	   * Despesa lançada do mês — a base do percentual.
14	   *
15	   * Sem a fatura: pagamento de fatura não tem categoria a atribuir, então
16	   * incluí-lo faria o percentual nunca chegar a zero e discordar de "Para onde
17	   * foi", que mede outra coisa.
18	   */
19	  monthOutCents: number;
20	  categories: { id: string; name: string }[];
21	};
22	
23	/** Grupos exibidos de saída; o resto vira "+N" para a lista não virar rolagem. */
24	const VISIBLE = 6;
25	
26	/**
27	 * Categorizar em lote — a dívida que trava o resto do painel.
28	 *
29	 * "Sem categoria 61%" aparecia como fato passivo em "Para onde foi". É o gargalo
30	 * de tudo que classifica: a régua de essencial, o ritmo, o estimado, o burn-up.
31	 * Enquanto for percentual, ninguém age; virando lista com botão, some.
32	 *
33	 * Agrupa por comerciante porque o custo real não é escolher a categoria, é fazer
34	 * isso quarenta vezes para a mesma padaria.
35	 */
36	export function UncategorizedSection({
37	  groups,
38	  totalCents,
39	  monthOutCents,
40	  categories,
41	}: Props) {
42	  const [open, setOpen] = useState(false);
43	  const mutation = useBulkCategorize();
44	
45	  if (groups.length === 0) return null;
46	
47	  const pct = monthOutCents > 0 ? Math.round((totalCents / monthOutCents) * 100) : 0;
48	  const shown = groups.slice(0, VISIBLE);
49	  const rest = groups.length - shown.length;
50	  const count = groups.reduce((s, g) => s + g.count, 0);
51	
52	  return (
53	    <section className="overflow-hidden rounded-xl border border-warning/30 bg-warning/[0.04]">
54	      <button
55	        type="button"
56	        onClick={() => setOpen((v) => !v)}
57	        aria-expanded={open}
58	        className="flex w-full items-start gap-2.5 px-4 py-3 text-left hover:bg-warning/[0.07]"
59	      >
60	        <Tag className="mt-0.5 size-4 shrink-0 text-warning" aria-hidden />
61	        <div className="min-w-0 flex-1">
62	          <p className="text-[13px] font-medium text-text">
63	            {count} {count === 1 ? 'lançamento' : 'lançamentos'} sem categoria ·{' '}
64	            {formatBRL(totalCents)}
65	          </p>
66	          <p className="mt-0.5 text-[11px] leading-relaxed text-text-muted">
67	            {pct > 0 ? `${pct}% da despesa lançada. ` : ''}
68	            Sem categoria o app não sabe o que é compromisso e o que é hábito — é o
69	            que limita o estimado e o ritmo.
70	          </p>
71	        </div>
72	        <ChevronRight
73	          className={cn(
74	            'mt-0.5 size-4 shrink-0 text-text-muted transition-transform',
75	            open && 'rotate-90',
76	          )}
77	          aria-hidden
78	        />
79	      </button>
80	
81	      {open ? (
82	        <ul className="border-t border-warning/20">
83	          {shown.map((group) => (
84	            <li
85	              key={group.key}
86	              className="flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-warning/10 px-4 py-2.5 last:border-b-0"
87	            >
