1	/**
2	 * Saldo correndo sobre a linha do tempo, e o recorte por mês.
3	 *
4	 * A propriedade que importa: `abertura(mês N+1) === fechamento(mês N)`.
5	 * Não é uma regra que alguém precisa lembrar de aplicar — cai da soma.
6	 */
7	
8	import { monthRange, type YearMonth } from '@/core/month';
9	import type { TimelineEvent } from '@/core/timeline/events';
10	
11	export type TimelinePoint = TimelineEvent & {
12	  /** Saldo depois de aplicar este evento. */
13	  balanceCents: number;
14	};
15	
16	export type TimelineDay = {
17	  date: string;
18	  events: TimelineEvent[];
19	  inCents: number;
20	  outCents: number;
21	  /** Saldo no fim do dia. */
22	  balanceCents: number;
23	  hasPlanned: boolean;
24	};
25	
26	export type TimelineMonth = {
27	  ym: YearMonth;
28	  days: TimelineDay[];
29	  openingCents: number;
30	  closingCents: number;
31	  inCents: number;
32	  /** Toda saída do mês, inclusive estimado — fecha o saldo. */
33	  outCents: number;
34	  /** Saída de lançamentos (realizado + previsto), sem o estimado. */
35	  bookedOutCents: number;
36	  /** Saída sintética do `forecast` (mediana do histórico). */
37	  estimatedOutCents: number;
38	  /** closing − opening. O que sobrou (ou faltou) no mês. */
39	  netCents: number;
40	  /** Algum dia do mês tem evento previsto. */
41	  hasPlanned: boolean;
42	};
43	
44	/** Aplica a âncora e devolve cada evento com o saldo resultante. */
45	export function runningBalance(
46	  events: ReadonlyArray<TimelineEvent>,
47	  anchorCents: number,
48	): TimelinePoint[] {
49	  let running = anchorCents;
50	  return events.map((event) => {
51	    running += event.deltaCents;
52	    return { ...event, balanceCents: running };
53	  });
54	}
55	
56	/**
57	 * Agrupa em dias e meses, carregando o saldo entre eles.
58	 *
59	 * `anchorCents` vale **antes** do primeiro evento da lista — normalmente o
60	 * saldo real no fim do mês anterior ao primeiro mês pedido.
61	 */
62	export function groupTimeline(input: {
63	  events: ReadonlyArray<TimelineEvent>;
64	  anchorCents: number;
65	  /** Meses a materializar, em ordem. Dias sem evento não viram linha. */
66	  months: ReadonlyArray<YearMonth>;
67	}): TimelineMonth[] {
68	  const byDate = new Map<string, TimelineEvent[]>();
69	  for (const event of input.events) {
70	    const list = byDate.get(event.date);
71	    if (list) list.push(event);
72	    else byDate.set(event.date, [event]);
73	  }
74	
75	  let running = input.anchorCents;
76	  const out: TimelineMonth[] = [];
77	
78	  for (const ym of input.months) {
79	    const { start, end } = monthRange(ym);
80	    const openingCents = running;
81	
82	    const dates = [...byDate.keys()]
83	      .filter((d) => d >= start && d <= end)
84	      .sort();
85	
86	    const days: TimelineDay[] = [];
87	    let inCents = 0;
88	    let outCents = 0;
89	    let bookedOutCents = 0;
90	    let estimatedOutCents = 0;
91	    let hasPlanned = false;
92	
93	    for (const date of dates) {
94	      const events = byDate.get(date)!;
95	      let dayIn = 0;
96	      let dayOut = 0;
97	      let dayPlanned = false;
98	
99	      for (const event of events) {
100	        if (event.deltaCents >= 0) dayIn += event.deltaCents;
101	        else {
102	          const abs = -event.deltaCents;
103	          dayOut += abs;
104	          if (event.kind === 'forecast') estimatedOutCents += abs;
